options.expressionToEvaluate:
const valor = {{1.1_user_domicilios}};

let lista;
if (Array.isArray(valor)) {
  lista = valor;
} else {
  try {
    lista = JSON.parse(valor);
  } catch (e) {
    lista = valor ? [String(valor)] : [];
  }
}
if (!Array.isArray(lista)) lista = [String(lista)];

return lista
  .map(d => String(d).trim())
  .filter(d => d !== '')
  .map(d => '• ' + d)
  .join('\n');

// Celular en formato E.164 para Chatwoot (+549 + código de área + número).
// Acepta 0 y 15: "03644 15-123456" → "+5493644123456".
// Si no se puede normalizar devuelve "", así Chatwoot no rechaza el contacto.
let d = String({{user_cel}} ?? "").replace(/\D/g, "");
if (d.startsWith("54")) d = d.slice(2);
if (d.startsWith("9") && d.length === 11) d = d.slice(1);
if (d.startsWith("0")) d = d.slice(1);
if (d.length === 12) {
  for (const n of [2, 3, 4]) {            // largo del código de área
    if (d.substr(n, 2) === "15") { d = d.slice(0, n) + d.slice(n + 2); break; }
  }
}
// Códigos de área argentinos: 11 (AMBA) o empiezan con 2 o 3
return /^(11\d{8}|[23]\d{9})$/.test(d) ? "+549" + d : "";

theme.customCss:
/* =====================================================================
   CUECCA · Tema para Typebot 3.18 (v3)
   Pegar en: Tema → Custom CSS. Fuente sugerida: Tema → Font = Poppins.
   Sin animaciones ni transiciones propias: el movimiento es el de Typebot.
   Las variables con !important pisan las que Typebot aplica en línea.
   ===================================================================== */

/* ---------- Tokens ---------- */
.typebot-container {
  --cuecca-navy: #233a6b;
  --cuecca-navy-2: #2f4d8a;
  --cuecca-navy-rgb: 35, 58, 107;
  --cuecca-ink: #1d2738;
  --cuecca-muted: #5d6879;
  --cuecca-faint: #9aa4b2;
  --cuecca-surface: #ffffff;
  --cuecca-bg: #edf1f5;
  --cuecca-line: #e4e9ef;
  --cuecca-focus: #1e63c6;

  /* Marca de agua */
  --cuecca-watermark: url("https://i.imgur.com/w99I6KY.png");
  --cuecca-watermark-opacity: 0.05;

  /* Colores del mosaico del logo */
  --px-red: #e53935;
  --px-orange: #f59e0b;
  --px-yellow: #f6c90e;
  --px-green: #2ea44f;
  --px-blue: #1e63c6;
  --px-violet: #7b3fb5;

  /* Contenedor: gris azulado con dos luces muy suaves de los colores de marca */
  --typebot-container-font-family: "Poppins" !important;
  --typebot-container-bg-color: var(--cuecca-bg) !important;
  --typebot-container-bg-image:
    radial-gradient(900px 520px at 100% 0%, rgba(30, 99, 198, 0.08), transparent 65%),
    radial-gradient(760px 480px at 0% 100%, rgba(46, 164, 79, 0.06), transparent 65%) !important;
  --typebot-chat-container-opacity: 0 !important;
  --typebot-chat-container-color: 29, 39, 56 !important;
  --typebot-chat-container-max-width: 760px !important;
  --typebot-chat-container-border-width: 0px !important;
  --typebot-chat-container-box-shadow: none !important;
  --typebot-chat-container-border-radius: 0px !important;

  /* Burbujas del bot */
  --typebot-host-bubble-bg-rgb: 255, 255, 255 !important;
  --typebot-host-bubble-opacity: 1 !important;
  --typebot-host-bubble-color: var(--cuecca-ink) !important;
  --typebot-host-bubble-border-width: 1px !important;
  --typebot-host-bubble-border-rgb: 228, 233, 239 !important;
  --typebot-host-bubble-border-opacity: 1 !important;
  --typebot-host-bubble-border-radius: 20px 20px 20px 6px !important;
  /* sombra corta: la burbuja cambia de tamaño mientras "escribe" */
  --typebot-host-bubble-box-shadow: 0 1px 2px rgba(29, 39, 56, 0.06) !important;

  /* Burbujas del socio */
  --typebot-guest-bubble-bg-rgb: var(--cuecca-navy-rgb) !important;
  --typebot-guest-bubble-opacity: 1 !important;
  --typebot-guest-bubble-color: #ffffff !important;
  --typebot-guest-bubble-border-width: 0px !important;
  --typebot-guest-bubble-border-radius: 20px 20px 6px 20px !important;
  --typebot-guest-bubble-box-shadow: 0 4px 14px rgba(35, 58, 107, 0.22) !important;

  /* Botones base (también estrellas de valoración) */
  --typebot-button-bg-rgb: var(--cuecca-navy-rgb) !important;
  --typebot-button-opacity: 1 !important;
  --typebot-button-color: #ffffff !important;
  --typebot-button-border-width: 0px !important;
  --typebot-button-border-radius: 14px !important;
  --typebot-button-box-shadow: none !important;

  /* Campo de texto: forma de píldora */
  --typebot-input-bg-rgb: 255, 255, 255 !important;
  --typebot-input-opacity: 1 !important;
  --typebot-input-color: var(--cuecca-ink) !important;
  --typebot-input-placeholder-color: var(--cuecca-faint) !important;
  --typebot-input-border-width: 1px !important;
  --typebot-input-border-rgb: 220, 226, 234 !important;
  --typebot-input-border-opacity: 1 !important;
  --typebot-input-border-radius: 26px !important;
  --typebot-input-box-shadow: 0 6px 20px rgba(29, 39, 56, 0.08) !important;

  isolation: isolate;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.typebot-container ::selection {
  background: rgba(30, 99, 198, 0.18);
}

/* ---------- Franja del logo ---------- */
.typebot-container::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 4px;
  z-index: 60;
  pointer-events: none;
  background: linear-gradient(
    90deg,
    var(--px-red) 0 16.66%,
    var(--px-orange) 16.66% 33.33%,
    var(--px-yellow) 33.33% 50%,
    var(--px-green) 50% 66.66%,
    var(--px-blue) 66.66% 83.33%,
    var(--px-violet) 83.33% 100%
  );
}

/* ---------- Marca de agua ---------- */
.typebot-container::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image: var(--cuecca-watermark);
  background-repeat: no-repeat;
  background-position: center;
  background-size: min(320px, 60%);
  opacity: var(--cuecca-watermark-opacity);
}

/* ---------- Burbujas del bot ---------- */
.typebot-host-bubble {
  font-size: 0.95rem;
  line-height: 1.6;
  letter-spacing: -0.005em;
  font-variant-numeric: tabular-nums; /* montos alineados en el detalle de deuda */
}
.typebot-host-bubble .slate-bold {
  color: var(--cuecca-navy);
  font-weight: 600;
}
.typebot-host-bubble .slate-italic {
  font-style: italic;
  color: var(--cuecca-muted);
}
.typebot-host-bubble a {
  color: var(--cuecca-focus);
  font-weight: 500;
  text-decoration: underline;
  text-decoration-color: rgba(30, 99, 198, 0.35);
  text-underline-offset: 3px;
}
.typebot-host-bubble a:hover {
  text-decoration-color: currentColor;
}
.typebot-host-bubble img,
.typebot-host-bubble video,
.typebot-host-bubble iframe {
  border-radius: 14px;
}

/* Puntos de "escribiendo" en el color de marca */
.bubble1,
.bubble2,
.bubble3 {
  background-color: var(--cuecca-navy);
  opacity: 0.4;
}

/* ---------- Burbujas del socio ---------- */
.typebot-guest-bubble {
  background-image: linear-gradient(135deg, var(--cuecca-navy-2), var(--cuecca-navy));
  font-size: 0.95rem;
  font-weight: 500;
  line-height: 1.45;
  letter-spacing: -0.005em;
}

/* ---------- Menú de opciones: tarjeta con lista ----------
   Cada opción tiene: marca de color redondeada (categoría), separador
   que no llega a los bordes, y flecha a la derecha. */
.typebot-buttons-input > [data-slot="list"] {
  gap: 0;
  width: min(100%, 360px);
  padding: 6px 0;
  background: var(--cuecca-surface);
  border: 1px solid var(--cuecca-line);
  border-radius: 18px;
  box-shadow: 0 1px 2px rgba(29, 39, 56, 0.04), 0 10px 28px rgba(29, 39, 56, 0.08);
}

/* Título de la tarjeta */
.typebot-buttons-input > [data-slot="list"]::before {
  content: "Elegí una opción";
  display: block;
  padding: 0.35rem 1.15rem 0.5rem;
  color: var(--cuecca-faint);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.typebot-buttons-input > [data-slot="list"] > span {
  display: block;
  width: 100%;
}

/* Separador entre opciones, con márgenes a los costados */
.typebot-buttons-input > [data-slot="list"] > span + span::before {
  content: "";
  position: absolute;
  top: 0;
  left: 1.15rem;
  right: 1rem;
  height: 1px;
  background: var(--cuecca-line);
  pointer-events: none;
}

.typebot-buttons-input .typebot-button {
  position: relative;
  width: 100%;
  min-height: 46px; /* área táctil cómoda en celular */
  justify-content: flex-start;
  align-items: center;
  text-align: left;
  gap: 0.55rem;
