/* ---------- Valoración: estrellas en naranja del logo ---------- */
.rating-icon-container svg {
  stroke: var(--px-orange);
}
.rating-icon-container.selected svg {
  fill: var(--px-orange);
}

/* ---------- Campo de texto y botón de enviar ---------- */
.typebot-input-form .typebot-button {
  background: linear-gradient(135deg, var(--cuecca-navy-2), var(--cuecca-navy));
  color: #ffffff;
  border: 0;
  border-radius: 999px;
  font-weight: 600;
  filter: none;
}
.typebot-input-form .typebot-button:hover {
  filter: brightness(1.1);
}
.typebot-input:focus-within {
  border-color: rgba(30, 99, 198, 0.55);
  box-shadow: 0 0 0 4px rgba(30, 99, 198, 0.12), 0 6px 20px rgba(29, 39, 56, 0.08);
}

/* ---------- Avatares ---------- */
.typebot-avatar-container span,
.guest-container > span {
  font-size: 26px;
  line-height: 1;
}
.typebot-avatar-container figure,
.guest-container figure {
  background: var(--cuecca-surface);
  box-shadow: 0 0 0 2px var(--cuecca-surface), 0 3px 10px rgba(29, 39, 56, 0.14);
}

/* ---------- Accesibilidad ---------- */
.typebot-button:focus-visible,
.typebot-input:focus-visible {
  outline: 3px solid var(--cuecca-focus);
  outline-offset: 2px;
}

/* ---------- Mobile ---------- */
@media (max-width: 480px) {
  .typebot-host-bubble,
  .typebot-guest-bubble {
    font-size: 0.9rem;
  }
  .typebot-buttons-input > [data-slot="list"] {
    width: 100%;
  }
}
